// "pl-PL", "pl_PL" or "pl" → "pl" when supported, else "".
function supported(locale) {
    var lower = String(locale || "").toLowerCase();
    // Brazilian Portuguese has its own table; other Portuguese locales use pt.
    if (/^pt[-_]br/.test(lower)) return "pt_br";
    var code = lower.slice(0, 2);
    return languages.indexOf(code) >= 0 ? code : "";
}
function get(lang, key) {
    var t = table[lang] || table.en;
    if (t[key] !== undefined) return t[key];
    // A key a Portuguese (Brazil) text still lacks reads in Portuguese, not English.
    if (lang === "pt_br" && table.pt[key] !== undefined) return table.pt[key];
    return table.en[key] !== undefined ? table.en[key] : key;
}
function format(text, values) {
    for (var k in values) text = text.replace("{" + k + "}", values[k]);
    return text;
}
